package com.gamehub.application;
import com.gamehub.infrastructure.Database; import java.sql.*; import java.time.*; import java.util.*;
public final class OperationsService { private final Database db; public OperationsService(Database db){this.db=db;}
 public long addStation(String code,String type,long hourlyPaisa)throws SQLException{if(code.isBlank()||hourlyPaisa<=0)throw new IllegalArgumentException("Station code/type/rate are required");try(var p=db.connection().prepareStatement("INSERT INTO gaming_stations(code,type,hourly_rate_paisa,status) VALUES(?,?,?,'AVAILABLE')",Statement.RETURN_GENERATED_KEYS)){p.setString(1,code);p.setString(2,type);p.setLong(3,hourlyPaisa);p.executeUpdate();try(var k=p.getGeneratedKeys()){k.next();return k.getLong(1);}}}
 public List<String> stations()throws SQLException{List<String> out=new ArrayList<>();try(var s=db.connection().createStatement();var r=s.executeQuery("SELECT code,type,status,hourly_rate_paisa FROM gaming_stations ORDER BY code")){while(r.next())out.add(r.getString(1)+" | "+r.getString(2)+" | "+r.getString(3)+" | PKR "+(r.getLong(4)/100.0));}return out;}
 public long reserve(long userId,long stationId,Instant start,Instant end)throws SQLException{if(!start.isBefore(end))throw new IllegalArgumentException("Start must precede end");String q="SELECT COUNT(*) FROM reservations WHERE status='CONFIRMED' AND (station_id=? OR user_id=?) AND starts_at<? AND ends_at>?";try(var p=db.connection().prepareStatement(q)){p.setLong(1,stationId);p.setLong(2,userId);p.setString(3,end.toString());p.setString(4,start.toString());try(var r=p.executeQuery()){if(r.next()&&r.getInt(1)>0)throw new IllegalStateException("Station or customer is already reserved");}}try(var p=db.connection().prepareStatement("INSERT INTO reservations(user_id,station_id,starts_at,ends_at,status) VALUES(?,?,?,?,'CONFIRMED')",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,userId);p.setLong(2,stationId);p.setString(3,start.toString());p.setString(4,end.toString());p.executeUpdate();try(var k=p.getGeneratedKeys()){k.next();return k.getLong(1);}}}
 public List<String> reservations(long userId)throws SQLException{List<String> out=new ArrayList<>();try(var p=db.connection().prepareStatement("SELECT id,station_id,starts_at,ends_at,status FROM reservations WHERE user_id=? ORDER BY starts_at")){p.setLong(1,userId);try(var r=p.executeQuery()){while(r.next())out.add("#"+r.getLong(1)+" station "+r.getLong(2)+" "+r.getString(3)+" -> "+r.getString(4)+" ["+r.getString(5)+"]");}}return out;}
 public void cancelReservation(long userId,long id)throws SQLException{try(var p=db.connection().prepareStatement("UPDATE reservations SET status='CANCELLED' WHERE id=? AND user_id=? AND status='CONFIRMED'")){p.setLong(1,id);p.setLong(2,userId);if(p.executeUpdate()!=1)throw new IllegalArgumentException("Reservation not found or already cancelled");}}
 public long startSession(long reservationId)throws SQLException{try(var q=db.connection().prepareStatement("SELECT status FROM reservations WHERE id=?");){q.setLong(1,reservationId);try(var r=q.executeQuery()){if(!r.next()||!"CONFIRMED".equals(r.getString(1)))throw new IllegalStateException("Reservation is not active");}}try(var q=db.connection().prepareStatement("SELECT COUNT(*) FROM sessions WHERE reservation_id=? AND status='ACTIVE'")){q.setLong(1,reservationId);try(var r=q.executeQuery()){r.next();if(r.getInt(1)>0)throw new IllegalStateException("Session already active");}}try(var p=db.connection().prepareStatement("INSERT INTO sessions(reservation_id,started_at,status) VALUES(?,? ,'ACTIVE')",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,reservationId);p.setString(2,Instant.now().toString());p.executeUpdate();try(var k=p.getGeneratedKeys()){k.next();return k.getLong(1);}}}
 public long finishSession(long id,long charge)throws SQLException{try(var p=db.connection().prepareStatement("UPDATE sessions SET ended_at=?,status='COMPLETED',charge_paisa=? WHERE id=?")){p.setString(1,Instant.now().toString());p.setLong(2,charge);p.setLong(3,id);if(p.executeUpdate()!=1)throw new IllegalArgumentException("Session not found");return id;}}
 public long recordPayment(long userId,long amount,String method,String ref)throws SQLException{if(amount<=0)throw new IllegalArgumentException("Amount must be positive");try(var p=db.connection().prepareStatement("INSERT INTO payments(user_id,amount_paisa,method,reference,status,created_at) VALUES(?,?,?,?,'SETTLED',?)",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,userId);p.setLong(2,amount);p.setString(3,method);p.setString(4,ref);p.setString(5,Instant.now().toString());p.executeUpdate();try(var k=p.getGeneratedKeys()){k.next();return k.getLong(1);}}}
 public long subscribeOrRenew(long userId,String plan,int days,long feePaisa)throws SQLException{if(plan.isBlank()||days<=0||feePaisa<=0)throw new IllegalArgumentException("Valid membership plan is required");Instant now=Instant.now();Instant end=now.plusSeconds(days*86400L);try(var q=db.connection().prepareStatement("SELECT id,ends_at FROM memberships WHERE user_id=? AND status='ACTIVE' ORDER BY ends_at DESC LIMIT 1")){q.setLong(1,userId);try(var r=q.executeQuery()){if(r.next()){long id=r.getLong(1);Instant prior=Instant.parse(r.getString(2));if(prior.isAfter(now))end=prior.plusSeconds(days*86400L);try(var u=db.connection().prepareStatement("UPDATE memberships SET plan=?,ends_at=?,status='ACTIVE' WHERE id=?")){u.setString(1,plan);u.setString(2,end.toString());u.setLong(3,id);u.executeUpdate();return id;}}}}try(var p=db.connection().prepareStatement("INSERT INTO memberships(user_id,plan,starts_at,ends_at,status) VALUES(?,?,?,?,'ACTIVE')",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,userId);p.setString(2,plan);p.setString(3,now.toString());p.setString(4,end.toString());p.executeUpdate();try(var k=p.getGeneratedKeys()){k.next();return k.getLong(1);}}}
 public String membership(long userId)throws SQLException{try(var p=db.connection().prepareStatement("SELECT plan,starts_at,ends_at,status FROM memberships WHERE user_id=? ORDER BY ends_at DESC LIMIT 1")){p.setLong(1,userId);try(var r=p.executeQuery()){return r.next()?r.getString(1)+" | "+r.getString(2)+" -> "+r.getString(3)+" ["+r.getString(4)+"]":"NONE";}}} public long settleSession(long userId,long sessionId,long amount,String method,String reference)throws SQLException{if(amount<=0||method.isBlank())throw new IllegalArgumentException("Valid payment is required");long charge;try(var q=db.connection().prepareStatement("SELECT s.charge_paisa,s.status,r.user_id FROM sessions s JOIN reservations r ON r.id=s.reservation_id WHERE s.id=?")){q.setLong(1,sessionId);try(var r=q.executeQuery()){if(!r.next()||!"COMPLETED".equals(r.getString(2))||r.getLong(3)!=userId)throw new IllegalStateException("Session is not payable");charge=r.getLong(1);}}if(amount<charge)throw new IllegalArgumentException("Payment is below the session charge");try(var q=db.connection().prepareStatement("SELECT COUNT(*) FROM payments WHERE reference=? AND status='SETTLED'")){q.setString(1,reference);try(var r=q.executeQuery()){r.next();if(r.getInt(1)>0)throw new IllegalStateException("Payment reference already settled");}}return recordPayment(userId,amount,method,reference);} public long reportCount(String table)throws SQLException{if(!Set.of("users","gaming_stations","reservations","sessions","payments","teams","tournaments","maintenance").contains(table))throw new IllegalArgumentException("Unsupported report");try(var s=db.connection().createStatement();var r=s.executeQuery("SELECT COUNT(*) FROM "+table)){r.next();return r.getLong(1);}}
}








